-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.100.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(1)
local x=np.transpose(np.astype(np.arange(12,"int64"):reshape({3,4}),"float32"),{2,1})
local before=x:tolist()
local out=np.zeros({4,3},"float32")
local y=r:permuted(x,2,out)
deep(y.dtype,"float32","1/(3, 4)/float32/transpose/1/out_new dtype")
deep(y:tolist(),{{0.0,4.0,8.0},{9.0,1.0,5.0},{6.0,2.0,10.0},{11.0,3.0,7.0}},"1/(3, 4)/float32/transpose/1/out_new values")
deep(x:tolist(),{{0.0,4.0,8.0},{1.0,5.0,9.0},{2.0,6.0,10.0},{3.0,7.0,11.0}},"1/(3, 4)/float32/transpose/1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"6c5f1f45de787048","1/(3, 4)/float32/transpose/1/out_new pcg")
cases=cases+1; end
